//! macOS pasteboard decisions, kept pure so every CI OS tests them: which
//! pasteboard types mark a copy as secret, when a change is our own write,
//! how types map to our Formats, and which app a Clip came from.

/// Pasteboard types that mark a copy as not to be recorded: the
/// nspasteboard.org markers plus the legacy ones it asks history apps to
/// honor. Universal Clipboard's `com.apple.is-remote-clipboard` is not one.
pub const SECRET_MARKERS: [&str; 7] = [
    "org.nspasteboard.ConcealedType",
    "org.nspasteboard.TransientType",
    "org.nspasteboard.AutoGeneratedType",
    "com.agilebits.onepassword",
    "de.petermaurer.TransientPasteboardType",
    "com.typeit4me.clipping",
    "Pasteboard generator type",
];

/// Whether the pasteboard's `types` (the union over all items) carry a
/// secret marker; then nothing of the copy may be read or stored.
pub fn is_marked_secret(types: &[String]) -> bool {
    types.iter().any(|t| SECRET_MARKERS.contains(&t.as_str()))
}

/// What a poll of `changeCount` found.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum PasteboardChange {
    Unchanged,
    /// Our own write (its count is what `clearContents()` returned): no
    /// ClipEvent, as X11 skips its own ownership. Not an Echo; the engine
    /// already bumped the Clip when it prepared the paste.
    Own,
    /// Another app copied: read it.
    Foreign,
}

/// Compares the count seen now with the last one seen and with the count of
/// our last write.
pub fn classify_change(last_seen: isize, current: isize, own: Option<isize>) -> PasteboardChange {
    if current == last_seen {
        PasteboardChange::Unchanged
    } else if own == Some(current) {
        PasteboardChange::Own
    } else {
        PasteboardChange::Foreign
    }
}

/// The `text/uri-list` Format (RFC 2483, CRLF-separated) for the
/// `public.file-url` of each pasteboard item; None when there are none.
pub fn uri_list(file_urls: &[String]) -> Option<String> {
    (!file_urls.is_empty()).then(|| file_urls.join("\r\n"))
}

/// The URLs of a `text/uri-list`, one per pasteboard item when writing.
/// Blank lines and `#` comment lines are dropped.
pub fn file_urls(uri_list: &str) -> Vec<String> {
    uri_list
        .lines()
        .map(str::trim)
        .filter(|l| !l.is_empty() && !l.starts_with('#'))
        .map(str::to_owned)
        .collect()
}

/// The source app of a copy: the copying app's own `org.nspasteboard.source`
/// bundle id when it set a non-empty one, else the frontmost app's bundle id
/// at poll time (an approximation: a background app's copy is attributed to
/// whatever is in front).
pub fn source_app(marker: Option<&str>, frontmost_bundle_id: Option<&str>) -> Option<String> {
    [marker, frontmost_bundle_id]
        .into_iter()
        .flatten()
        .find(|id| !id.is_empty())
        .map(str::to_owned)
}

/// Added (with empty data) to every write of ours, so other history apps
/// don't record our paste again.
pub const TRANSIENT_MARKER: &str = "org.nspasteboard.TransientType";
/// The source app's bundle id; we write the empty string, which
/// nspasteboard.org allows.
pub const SOURCE_MARKER: &str = "org.nspasteboard.source";

/// Our Format MIME type and the pasteboard type (UTI) it is read from and
/// written to. Files go through `FILE_URL_UTI`, one per pasteboard item.
pub const FORMAT_UTIS: [(&str, &str); 3] = [
    ("text/plain;charset=utf-8", "public.utf8-plain-text"),
    ("text/html", "public.html"),
    ("image/png", "public.png"),
];
pub const FILE_URL_UTI: &str = "public.file-url";
pub const URI_LIST_MIME: &str = "text/uri-list";

#[cfg(test)]
mod tests {
    use super::*;

    fn types(t: &[&str]) -> Vec<String> {
        t.iter().map(|s| s.to_string()).collect()
    }

    #[test]
    fn each_nspasteboard_org_marker_makes_the_copy_secret() {
        for m in [
            "org.nspasteboard.ConcealedType",
            "org.nspasteboard.TransientType",
            "org.nspasteboard.AutoGeneratedType",
            "com.agilebits.onepassword",
            "de.petermaurer.TransientPasteboardType",
            "com.typeit4me.clipping",
            "Pasteboard generator type",
        ] {
            assert!(is_marked_secret(&types(&["public.utf8-plain-text", m])), "{m}");
        }
    }

    #[test]
    fn ordinary_and_universal_clipboard_copies_are_not_secret() {
        let t = types(&["public.utf8-plain-text", "public.html", "com.apple.is-remote-clipboard", "org.nspasteboard.source"]);
        assert!(!is_marked_secret(&t));
        assert!(!is_marked_secret(&[]));
    }

    #[test]
    fn change_is_ours_only_when_the_count_matches_our_write() {
        use PasteboardChange::*;
        assert_eq!(classify_change(5, 5, None), Unchanged);
        assert_eq!(classify_change(6, 6, Some(6)), Unchanged);
        assert_eq!(classify_change(5, 6, Some(6)), Own);
        // Another app copied after our write: ownership moved on.
        assert_eq!(classify_change(5, 7, Some(6)), Foreign);
        assert_eq!(classify_change(5, 6, None), Foreign);
    }

    #[test]
    fn file_urls_become_one_uri_list_and_back() {
        let urls = vec!["file:///a".to_string(), "file:///b%20c".to_string()];
        assert_eq!(uri_list(&urls).as_deref(), Some("file:///a\r\nfile:///b%20c"));
        assert_eq!(uri_list(&[]), None);
        assert_eq!(file_urls("file:///a\r\n# comment\n\nfile:///b\r\n"), ["file:///a", "file:///b"]);
    }

    #[test]
    fn source_app_prefers_the_copying_apps_own_marker() {
        assert_eq!(source_app(Some("com.x"), Some("com.y")).as_deref(), Some("com.x"));
        // nspasteboard.org allows an empty source: fall back to the frontmost app.
        assert_eq!(source_app(Some(""), Some("com.y")).as_deref(), Some("com.y"));
        assert_eq!(source_app(None, Some("")), None);
        assert_eq!(source_app(None, None), None);
    }
}
